import string


class Base62Encoder:
    """
    Converts numbers to Base62 strings for minimal URL length.
    Example: ID 1000000 → "4c92" (4 characters)
    """

    ALPHABET = string.digits + string.ascii_lowercase + string.ascii_uppercase
    BASE = len(ALPHABET)  # 62

    @staticmethod
    def encode(num: int) -> str:
        """
        Convert integer ID to Base62 string.

        Example:
        - ID 1 → "1"
        - ID 62 → "10"
        - ID 1000000 → "4c92"
        """
        if num == 0:
            return Base62Encoder.ALPHABET[0]

        result = []
        while num > 0:
            remainder = num % Base62Encoder.BASE
            result.append(Base62Encoder.ALPHABET[remainder])
            num //= Base62Encoder.BASE

        return ''.join(reversed(result))

    @staticmethod
    def decode(short_url: str) -> int:
        """
        Convert Base62 string back to integer ID.
        Used for reverse lookups if needed.
        """
        num = 0
        for char in short_url:
            num = num * Base62Encoder.BASE + Base62Encoder.ALPHABET.index(char)
        return num

# Example Usage:
# encoder = Base62Encoder()
# short = encoder.encode(123456)  # "w7e"
# original = encoder.decode("w7e")  # 123456
